structured_output.command:
awk '
BEGIN {
  OFS=","
  today="2025-08-12"; s7="2025-08-06"; s30="2025-07-14"; sm="2025-08-01"
  print "period","severity","count"
}
{
  d=substr(FILENAME,11,10)
  if (match($0, /\[(ERROR|WARNING|INFO)\]/)) {
    sev=substr($0,RSTART+1,RLENGTH-2)
    c["total",sev]++
    if (d==today) c["today",sev]++
    if (d>=s7 && d<=today) c["last_7_days",sev]++
    if (d>=s30 && d<=today) c["last_30_days",sev]++
    if (d>=sm && d<=today) c["month_to_date",sev]++
  }
}
END {
  split("today last_7_days last_30_days month_to_date total", periods, " ")
  split("ERROR WARNING INFO", severities, " ")
  for (i=1;i<=5;i++) for (j=1;j<=3;j++) print periods[i], severities[j], c[periods[i],severities[j]]+0
}
' /app/logs/*.log > /tmp/verify.csv && diff -u /app/summary.csv /tmp/verify.csv && echo VERIFIED

